sys_script.script:
(function(current) {
    // Only process approvals for our absence RITMs
    var sourceTable = current.getValue('source_table');
    if (sourceTable != 'sc_req_item') return;

    var ritmId = current.getValue('sysapproval');
    if (!ritmId) return;

    var ritm = new GlideRecord('sc_req_item');
    if (!ritm.get(ritmId)) return;

    // Check this is our catalog item
    var catItemGR = new GlideRecord('sc_cat_item');
    catItemGR.addQuery('name', 'Continuity Absence Request');
    catItemGR.addQuery('sys_scope', '35f8e15683a85310e1615529feaad35a');
    catItemGR.query();
    if (!catItemGR.next()) return;
    if (ritm.getValue('cat_item') != catItemGR.getUniqueValue()) return;

    var state = current.getValue('state');
    var freezeSvc = new x_2316178_contin_0.FreezeService();

    if (state == 'approved') {
        ritm.setValue('approval', 'approved');
        ritm.update();

        // Get absence dates and user from RITM variables
        var absenceStart = ritm.variables.absence_start.toString();
        var absenceEnd = ritm.variables.absence_end.toString();
        var userId = ritm.getValue('opened_by') || ritm.getValue('requested_for');

        // Create freeze Time Cards (idempotent)
        if (absenceStart && absenceEnd && userId) {
            freezeSvc.createFreezeCards(userId, ritmId, absenceStart, absenceEnd);
        }
    } else if (state == 'rejected') {
        // Clean up any freeze cards that may have been created before rejection
        var userId2 = ritm.getValue('opened_by') || ritm.getValue('requested_for');
        if (userId2) {
            freezeSvc.cleanupFreezeCards(userId2, ritmId);
        }

        ritm.setValue('approval', 'rejected');
        ritm.setValue('stage', 'Request Cancelled');
        ritm.update();
    }
})(current);
